-- Auth and catalog use separate databases, so store_id cannot be a real FK.
-- This UUID is the deterministic DEMO "studio" store generated by
-- services/catalog/database/seeders/DemoCatalogDataset.php
-- (uuid5 of "https://rentify.example/demo/catalog/v1/store/studio").
-- Run `make seed-catalog` (or `make seed`) so the matching store row exists.
UPDATE users
SET store_id = '4122d059-3fc9-5cef-b48a-763053376266',
    updated_at = NOW()
WHERE email = 'manager@shop.local'
  AND role = 'store_manager'
  AND store_id IS NULL;
